local({
  score <- if_else(as.numeric(X1SES1) %in% c(-9, -8), NA_real_, as.numeric(X1SES1))
  low <- stats::quantile(score, 0.4, na.rm = TRUE, names = FALSE)
  high <- stats::quantile(score, 0.6, na.rm = TRUE, names = FALSE)
  case_when(score <= low ~ "Low", score <= high ~ "Medium", score > high ~ "High", .default = "Unknown")
})

local({
  maths <- recode_values(as.numeric(S1HRMHOMEWK), -7 ~ 0, 1 ~ 0.5, 2 ~ 1.5, 3 ~ 2.5, 4 ~ 3.5, 5 ~ 4.5, 6 ~ 5)
  science <- recode_values(as.numeric(S1HRSHOMEWK), -7 ~ 0, 1 ~ 0.5, 2 ~ 1.5, 3 ~ 2.5, 4 ~ 3.5, 5 ~ 4.5, 6 ~ 5)
  other <- recode_values(as.numeric(S1HROTHHOMWK), 1 ~ 0.5, 2 ~ 1.5, 3 ~ 2.5, 4 ~ 3.5, 5 ~ 4.5, 6 ~ 5)
  maths + science + other
})
